package com.opentv.app.ui;
import android.view.*;import android.widget.TextView;import androidx.annotation.NonNull;import androidx.recyclerview.widget.RecyclerView;import com.opentv.app.R;import java.util.List;
public class NavAdapter extends RecyclerView.Adapter<NavAdapter.Holder>{public static class Item{public final String label,url;public final boolean favorites,settings;public Item(String l,String u){this(l,u,false,false);}public Item(String l,String u,boolean f,boolean s){label=l;url=u;favorites=f;settings=s;}}public interface Listener{void onClick(Item i);}private final List<Item>items;private final Listener listener;public NavAdapter(List<Item>i,Listener l){items=i;listener=l;}
@NonNull public Holder onCreateViewHolder(@NonNull ViewGroup p,int t){return new Holder(LayoutInflater.from(p.getContext()).inflate(R.layout.item_nav,p,false));}public void onBindViewHolder(@NonNull Holder h,int p){Item i=items.get(p);h.text.setText(i.label);h.text.setOnClickListener(v->listener.onClick(i));}public int getItemCount(){return items.size();}static class Holder extends RecyclerView.ViewHolder{final TextView text;Holder(View v){super(v);text=v.findViewById(R.id.navText);}}}
